const C001_SOURCE_BOUNDS = {
  minX: 360,
  minY: 72,
  maxX: 2835,
  maxY: 1682
};

// Display-only extents measured from the approved No.3 SVG. Source paths and
// resizing geometry remain unchanged.
const C001_DIELINE_SOURCE_BOUNDS = {
  minX: 389.223,
  minY: 95.835,
  maxX: 2810.064,
  maxY: 1657.728
};

const C001_BLEED_SOURCE_BOUNDS = {
  minX: 380.691,
  minY: 87.144,
  maxX: 2818.568,
  maxY: 1666.045
};

const C001_LAYOUT_UNIT = 25.4 / 72;

const C001_PANEL_ANCHORS = {
  baseLeftX: 460.09,
  baseRightX: 1239.618,
  sideBackRightX: 1636.469,
  lidRightX: 2415.993,
  sideFrontRightX: 2810.064,
  mainTopY: 487.016,
  mainBottomY: 1266.547
};

function C001_layoutNum(value) {
  return +(+value).toFixed(4);
}
function C001_lerp(a, b, t) {
  return a + ((b - a) * t);
}

function C001_piecewiseMap(value, stops) {
  if (value <= stops[0].source) return value + (stops[0].target - stops[0].source);
  for (let i = 0; i < stops.length - 1; i += 1) {
    const a = stops[i];
    const b = stops[i + 1];
    if (value <= b.source) {
      const t = (value - a.source) / (b.source - a.source);
      return C001_lerp(a.target, b.target, t);
    }
  }
  const last = stops[stops.length - 1];
  return value + (last.target - last.source);
}

function C001_makePanelMap(cfg) {
  const a = C001_PANEL_ANCHORS;
  const baseScale = cfg.D / 275;
  const heightScale = cfg.H / 140;
  const lidScale = cfg.D / 275;
  const verticalScale = cfg.W / 277;

  const baseRightX = a.baseLeftX + ((a.baseRightX - a.baseLeftX) * baseScale);
  const sideBackRightX = baseRightX + ((a.sideBackRightX - a.baseRightX) * heightScale);
  const lidRightX = sideBackRightX + ((a.lidRightX - a.sideBackRightX) * lidScale);
  const sideFrontRightX = lidRightX + ((a.sideFrontRightX - a.lidRightX) * heightScale);

  const centerY = (a.mainTopY + a.mainBottomY) / 2;
  const mainHeight = (a.mainBottomY - a.mainTopY) * verticalScale;
  const mainTopY = centerY - (mainHeight / 2);
  const mainBottomY = centerY + (mainHeight / 2);

  const xStops = [
    { source: a.baseLeftX, target: a.baseLeftX },
    { source: a.baseRightX, target: baseRightX },
    { source: a.sideBackRightX, target: sideBackRightX },
    { source: a.lidRightX, target: lidRightX },
    { source: a.sideFrontRightX, target: sideFrontRightX }
  ];
  const yStops = [
    { source: a.mainTopY, target: mainTopY },
    { source: a.mainBottomY, target: mainBottomY }
  ];

  return {
    unit: C001_LAYOUT_UNIT,
    xStops,
    yStops,
    panels: {
      glue: { left: 389.223, right: a.baseLeftX },
      base: { left: a.baseLeftX, right: baseRightX },
      sideBack: { left: baseRightX, right: sideBackRightX },
      lidTop: { left: sideBackRightX, right: lidRightX },
      sideFront: { left: lidRightX, right: sideFrontRightX },
      main: { top: mainTopY, bottom: mainBottomY }
    }
  };
}

function C001_mapSource(layout, x, y) {
  const map = layout.panelMap;
  return {
    x: C001_layoutNum(C001_piecewiseMap(x, map.xStops) * map.unit),
    y: C001_layoutNum(C001_piecewiseMap(y, map.yStops) * map.unit)
  };
}

function C001_getLayout(input) {
  const cfg = typeof C001_resolveConfig === "function" ? C001_resolveConfig(input) : {
    W: Number(input && input.W) || 277,
    D: Number(input && input.D) || 275,
    H: Number(input && input.H) || 140
  };
  const panelMap = C001_makePanelMap(cfg);
  const s = C001_SOURCE_BOUNDS;
  const mapLayout = { panelMap };
  const topLeft = C001_mapSource(mapLayout, s.minX, s.minY);
  const bottomRight = C001_mapSource(mapLayout, s.maxX, s.maxY);
  const bounds = {
    minX: topLeft.x,
    minY: topLeft.y,
    maxX: bottomRight.x,
    maxY: bottomRight.y
  };
  bounds.width = C001_layoutNum(bounds.maxX - bounds.minX);
  bounds.height = C001_layoutNum(bounds.maxY - bounds.minY);

  function mappedBounds(sourceBounds) {
    const min = C001_mapSource(mapLayout, sourceBounds.minX, sourceBounds.minY);
    const max = C001_mapSource(mapLayout, sourceBounds.maxX, sourceBounds.maxY);
    return {
      minX: min.x,
      minY: min.y,
      maxX: max.x,
      maxY: max.y,
      width: C001_layoutNum(max.x - min.x),
      height: C001_layoutNum(max.y - min.y)
    };
  }

  const dielineBounds = mappedBounds(C001_DIELINE_SOURCE_BOUNDS);
  const bleedBounds = mappedBounds(C001_BLEED_SOURCE_BOUNDS);
  return {
    cfg,
    bounds,
    renderBounds: bounds,
    dielineBounds,
    bleedBounds,
    panelMap,
    mapPoint(x, y) {
      return C001_mapSource(this, x, y);
    },
    transform: { a: C001_LAYOUT_UNIT, b: 0, c: 0, d: C001_LAYOUT_UNIT, e: 0, f: 0 },
    cutElements: C001_CUT_ELEMENTS,
    foldElements: C001_FOLD_ELEMENTS,
    bleedElements: C001_BLEED_ELEMENTS,
    guideElements: C001_GUIDE_ELEMENTS
  };
}
